const params = msg.rpcParams || {};

// Get target datetime
let targetDate;
if (params.dateTimeUtc) {
    targetDate = new Date(params.dateTimeUtc);
} else {
    // Use current time
    targetDate = new Date();
}

// Timezone handling (for display, actual time is UTC-based)
const timezone = params.timezone || "Europe/Istanbul";

// What to sync
const syncGateway = params.syncGateway !== false; // default true
const syncInverter = params.syncInverter !== false; // default true

// Store in flow context
flow.set("sdt_target_date", targetDate.toISOString());
flow.set("sdt_timezone", timezone);
flow.set("sdt_sync_gateway", syncGateway);
flow.set("sdt_sync_inverter", syncInverter);
flow.set("sdt_rpc_response_topic", msg.rpcResponseTopic);
flow.set("sdt_results", { gateway: null, inverter: null });

msg.targetDate = targetDate;
msg.timezone = timezone;
msg.syncGateway = syncGateway;
msg.syncInverter = syncInverter;
msg.operationType = "write";

node.status({ fill: "blue", shape: "dot", text: targetDate.toISOString() });

return msg;

const opType = msg.operationType || 'write';

if (opType === 'read') {
    return [msg, null];
} else {
    return [null, msg];
}

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 21,
    quantity: 3
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 3) {
    node.error("Invalid modbus response");
    return null;
}

// Registers are packed: each 16-bit register contains 2 bytes
// Register 21: High=Year (based on 2000), Low=Month
// Register 22: High=Day, Low=Hour  
// Register 23: High=Minute, Low=Second

const reg21 = data[0] || 0;
const reg22 = data[1] || 0;
const reg23 = data[2] || 0;

const year = 2000 + ((reg21 >> 8) & 0xFF);  // High byte of reg21
const month = reg21 & 0xFF;                  // Low byte of reg21
const day = (reg22 >> 8) & 0xFF;            // High byte of reg22
const hour = reg22 & 0xFF;                   // Low byte of reg22
const minute = (reg23 >> 8) & 0xFF;         // High byte of reg23
const second = reg23 & 0xFF;                 // Low byte of reg23

node.warn(`Parsed: ${year}-${month}-${day} ${hour}:${minute}:${second}`);
node.warn(`Raw registers: [${reg21}, ${reg22}, ${reg23}] = [0x${reg21.toString(16)}, 0x${reg22.toString(16)}, 0x${reg23.toString(16)}]`);

const inverterTime = `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}:${String(second).padStart(2,'0')}`;

msg.payload = {
    kind: "DateTimeState",
    timestampUtc: new Date().toISOString(),
    inverterDateTime: inverterTime,
    inverterDateTimeRaw: {
        year: year,
        month: month,
        day: day,
        hour: hour,
        minute: minute,
        second: second,
        rawRegisters: [reg21, reg22, reg23]
    }
};

return msg;

const syncGateway = msg.syncGateway;
const syncInverter = msg.syncInverter;

if (syncGateway) {
    // First sync gateway
    return [msg, null];
} else if (syncInverter) {
    // Skip gateway, go to inverter
    return [null, msg];
} else {
    // Nothing to sync
    node.warn("Nothing to sync");
    return [null, null];
}

const targetDate = new Date(flow.get("sdt_target_date"));
const timezone = flow.get("sdt_timezone");

// Format for date command: "YYYY-MM-DD HH:MM:SS"
const year = targetDate.getUTCFullYear();
const month = String(targetDate.getUTCMonth() + 1).padStart(2, '0');
const day = String(targetDate.getUTCDate()).padStart(2, '0');
const hour = String(targetDate.getUTCHours()).padStart(2, '0');
const minute = String(targetDate.getUTCMinutes()).padStart(2, '0');
const second = String(targetDate.getUTCSeconds()).padStart(2, '0');

const dateStr = `${year}-${month}-${day} ${hour}:${minute}:${second}`;

// Build single command string
msg.payload = `timedatectl set-timezone ${timezone} && date -s '${dateStr}' && hwclock -w`;

node.status({ fill: "blue", shape: "dot", text: "Setting gateway time..." });

return msg;

const results = flow.get("sdt_results") || {};
results.gateway = {
    success: true,
    message: "Gateway time synchronized",
    output: msg.payload
};
flow.set("sdt_results", results);

node.status({ fill: "green", shape: "dot", text: "Gateway OK" });

// Check if we need to sync inverter
const syncInverter = flow.get("sdt_sync_inverter");
if (syncInverter) {
    return msg;
} else {
    // Go to final response
    return null;
}

const results = flow.get("sdt_results") || {};
results.gateway = {
    success: false,
    message: "Gateway time sync failed",
    error: msg.payload
};
flow.set("sdt_results", results);

node.status({ fill: "red", shape: "dot", text: "Gateway FAILED" });
node.error("Gateway time sync failed: " + msg.payload);

// Continue to inverter anyway
const syncInverter = flow.get("sdt_sync_inverter");
if (syncInverter) {
    return msg;
}
return null;

const targetDateStr = flow.get("sdt_target_date");
const timezone = flow.get("sdt_timezone") || "Europe/Istanbul";

// Parse the target date
const targetDate = new Date(targetDateStr);

// Get local time components based on timezone
// Use toLocaleString to get the correct local time
const options = { 
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
};

const localStr = targetDate.toLocaleString('en-GB', options);
// Format: "DD/MM/YYYY, HH:MM:SS"
const parts = localStr.split(/[\/, :]+/);

const day = parseInt(parts[0]);
const month = parseInt(parts[1]);
const year = parseInt(parts[2]) - 2000;  // Based on 2000
const hour = parseInt(parts[3]);
const minute = parseInt(parts[4]);
const second = parseInt(parts[5]);

node.warn(`Local time for ${timezone}: ${year+2000}-${month}-${day} ${hour}:${minute}:${second}`);

const writes = [
    { register: 21, value: year, name: "Year" },
    { register: 22, value: month, name: "Month" },
    { register: 23, value: day, name: "Day" },
    { register: 24, value: hour, name: "Hour" },
    { register: 25, value: minute, name: "Minute" },
    { register: 26, value: second, name: "Second" }
];

global.set("sdt_write_queue", writes);
global.set("sdt_write_index", 0);
global.set("sdt_write_results", []);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} inverter writes` });

return msg;

const writes = global.get("sdt_write_queue") || [];
const index = global.get("sdt_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("sdt_write_queue") || [];
let index = global.get("sdt_write_index") || 0;
const results = global.get("sdt_write_results") || [];

const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("sdt_write_results", results);
}

index++;
global.set("sdt_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done
global.set("sdt_write_queue", null);
global.set("sdt_write_index", null);

const flowResults = flow.get("sdt_results") || {};
flowResults.inverter = {
    success: true,
    message: `Successfully wrote ${results.length} time register(s)`,
    writes: results
};
flow.set("sdt_results", flowResults);

node.status({ fill: "green", shape: "dot", text: `Inverter time set!` });

return [null, msg];

const results = flow.get("sdt_results") || {};
const rpcResponseTopic = flow.get("sdt_rpc_response_topic");
const targetDate = flow.get("sdt_target_date");
const timezone = flow.get("sdt_timezone");

// Clear flow context
flow.set("sdt_results", null);
flow.set("sdt_rpc_response_topic", null);
flow.set("sdt_target_date", null);
flow.set("sdt_timezone", null);
flow.set("sdt_sync_gateway", null);
flow.set("sdt_sync_inverter", null);

const success = 
    (!results.gateway || results.gateway.success) && 
    (!results.inverter || results.inverter.success);

msg.payload = {
    kind: "SetDateTimeResponse",
    success: success,
    targetDateTime: targetDate,
    timezone: timezone,
    gateway: results.gateway,
    inverter: results.inverter
};

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
